{"script": "python3 << 'EOF'
import FreeCAD
import Part

# Open the precondition file
doc = FreeCAD.open("/home/user/Precondition_Unnamed.FCStd")

# Find the Sketch object
for obj in doc.Objects:
    if obj.TypeId == "Sketcher::SketchObject":
        print(f"Found Sketch: {obj.Name}")

        # Get sketch geometry
        if hasattr(obj, 'Geometry'):
            print(f"Number of geometry elements: {len(obj.Geometry)}")
            for i, geom in enumerate(obj.Geometry):
                print(f"\n  Geometry {i}: {geom.TypeId}")
                if hasattr(geom, 'Curve'):
                    curve = geom.Curve
                    print(f"    Curve type: {type(curve).__name__}")
                    if hasattr(curve, 'Center'):
                        print(f"    Center: {curve.Center}")
                    if hasattr(curve, 'MajorRadius'):
                        print(f"    MajorRadius: {curve.MajorRadius}")
                    if hasattr(curve, 'MinorRadius'):
                        print(f"    MinorRadius: {curve.MinorRadius}")
                    if hasattr(curve, 'Vertex1') and hasattr(curve, 'Vertex2'):
                        print(f"    Vertex1: {curve.Vertex1}")
                        print(f"    Vertex2: {curve.Vertex2}")

        # Get constraints
        if hasattr(obj, 'Constraints'):
            print(f"\nNumber of constraints: {len(obj.Constraints)}")
            for c in obj.Constraints:
                print(f"  Constraint: {c.Name} - {c.Type}")

        # Try to get the shape
        try:
            shape = obj.Shape
            print(f"\nShape type: {shape.ShapeType}")
            print(f"Edge count: {len(shape.Edges)}")
            for i, edge in enumerate(shape.Edges):
                print(f"  Edge {i}: {edge.Curve.__class__.__name__}")
                print(f"    First point: {edge.FirstVertex().Point}")
                print(f"    Last point: {edge.LastVertex().Point}")
        except Exception as e:
            print(f"Error getting shape: {e}")

FreeCAD.closeDocument(doc.Name)
EOF"}

